// Kotlin Multiplatform: Whisper base.en on ONNX Runtime 1.22.0, the model side
// of speech recognition, shared by the Android and iOS apps.
// The JS reference (src/*.js at the repo root, through transformers.js 3.8.1) is
// the source of truth, and android/models/src/commonTest/resources/golden/whisper.json
// (generated by tools/golden/models.mjs) pins this port to it, run on the host
// JVM, on the iOS simulator, and on Android through `:speech:connectedDebugAndroidTest`.
//
// ONNX Runtime reaches this module two ways, behind commonMain's `OnnxSession`
// port: the JVM target uses ORT's Java API (ai.onnxruntime), from the desktop jar
// in jvmTest and from the pinned AAR on Android (:speech supplies it), and iOS
// uses ORT's C API through the cinterop shim in src/nativeInterop/ (no dlopen and
// no custom ops: the default CPU provider, as the reference's
// executionProviders ['cpu']). The iOS xcframework is the one
// tools/fetch-onnxruntime.mjs fetches and models/onnxruntime.SHA256SUMS pins; it
// is unpacked under models/build/, never under src/, and both the simulator and
// device slices are linked from there.
//
// The model itself is not in the repository's build: it is a downloaded, pinned
// directory (models/whisper-base.en, checked by tools/fetch-model.mjs --verify).
// jvmTest reads it through the MODEL_DIR environment variable, which Gradle
// fills in below (default <repo>/models/whisper-base.en). On iOS the test binary
// has no bundle holding the test resources or the model, so it reads both from
// the host's disk: `syncIosTestResources` lays the goldens and the fixture WAVs
// out in models/build/ios-test-resources/ (golden/, fixtures/speech/), and
// simctl passes the locations in with the SIMCTL_CHILD_ prefix:
//   SIMCTL_CHILD_GOLDEN_DIR=/<abs>/android/models/build/ios-test-resources \
//   SIMCTL_CHILD_MODEL_DIR=/<abs>/models/whisper-base.en \
//     ./gradlew :models:iosSimulatorArm64Test
//
// The fixture WAVs and expected.json are copied into the test resources pinned
// by hash (speech-fixtures.SHA256SUMS), exactly as :core pins its turn
// scenarios.
plugins {
    alias(libs.plugins.kotlin.multiplatform)
}

val ortXcframework = rootProject.layout.projectDirectory.dir("models/build/onnxruntime-ios/onnxruntime.xcframework")
val ortSlices = mapOf("iosArm64" to "ios-arm64", "iosSimulatorArm64" to "ios-arm64_x86_64-simulator")
val defaultModelDir = rootProject.file("../models/whisper-base.en").absolutePath

// tests/fixtures/speech, pinned by hash, as :core pins its scenarios.
val syncSpeechFixtures = tasks.register<CopyPinnedAssets>("syncSpeechFixtures") {
    sourceDir = file("${rootProject.projectDir}/../tests/fixtures/speech")
    pins = file("speech-fixtures.SHA256SUMS")
    assetPath = "fixtures/speech"
    outputDir = layout.buildDirectory.dir("generated/speech-fixture-resources")
}

// iOS reads test resources from GOLDEN_DIR = models/build/ios-test-resources.
val syncIosTestResources = tasks.register<Sync>("syncIosTestResources") {
    from("src/commonTest/resources")
    from(syncSpeechFixtures)
    into(layout.buildDirectory.dir("ios-test-resources"))
}

// As :core does: schema.json and core's main resources beside the test executable,
// in case anything reaches I18n.default (English parsing should not).
val copyIosTestBundleResources = tasks.register<Copy>("copyIosTestBundleResources") {
    from("${rootProject.projectDir}/core/src/commonMain/resources")
    from("${rootProject.projectDir}/../tools/schema.json")
    into(layout.buildDirectory.dir("bin/iosSimulatorArm64/debugTest"))
    mustRunAfter(tasks.matching { it.name == "linkDebugTestIosSimulatorArm64" })
}

kotlin {
    jvmToolchain(21)
    jvm()
    listOf(iosArm64(), iosSimulatorArm64()).forEach { target ->
        val slice = ortXcframework.dir(ortSlices.getValue(target.name)).asFile.absolutePath
        target.compilations.getByName("main").cinterops.create("onnxruntime") {
            definitionFile.set(project.file("src/nativeInterop/cinterop/onnxruntime.def"))
            packageName("org.ssa.assistant.models.ort")
            includeDirs("$slice/onnxruntime.framework/Headers")
        }
        target.binaries.all {
            linkerOpts("-F$slice", "-framework", "onnxruntime", "-lc++",
                       "-framework", "Foundation", "-weak_framework", "CoreML")
        }
    }
    sourceSets {
        commonMain.dependencies {
            implementation(project(":core"))
            implementation(libs.kotlinx.coroutines.core)
        }
        commonTest {
            resources.srcDir(syncSpeechFixtures)
            dependencies {
                implementation(kotlin("test"))
            }
        }
        // Decision 3: the AAR supplies ONNX Runtime on Android, so the Java API
        // is only a compile-time dependency of jvmMain.
        jvmMain.dependencies {
            compileOnly(libs.onnxruntime.desktop)
        }
        jvmTest.dependencies {
            implementation(kotlin("test-junit"))
            implementation(libs.onnxruntime.desktop)
        }
    }
}

tasks.matching { it.name.startsWith("cinteropOnnxruntime") }.configureEach { dependsOn(":unpackOnnxRuntimeIos") }
// The JVM side uses only the AAR and the jar, so it no longer needs the iOS zip.
tasks.matching { it.name == "compileKotlinJvm" || it.name == "jvmTest" }.configureEach { dependsOn(":verifyOnnxRuntimeJava") }
tasks.matching { it.name == "iosSimulatorArm64Test" }.configureEach { dependsOn(syncIosTestResources, copyIosTestBundleResources) }

tasks.named<Test>("jvmTest") {
    useJUnit()
    val modelDir = System.getenv("MODEL_DIR")?.takeIf { it.isNotEmpty() } ?: defaultModelDir
    environment("MODEL_DIR", modelDir)
    inputs.property("modelDir", modelDir)
    maxHeapSize = "2g"
}
tasks.withType<AbstractTestTask>().configureEach {
    testLogging {
        events("passed", "failed", "skipped")
        showStandardStreams = true
        showStackTraces = true
        exceptionFormat = org.gradle.api.tasks.testing.logging.TestExceptionFormat.FULL
    }
}
